#pragma once
#include "Tab5MeshModel.h"
namespace Tab5MeshCodec {
constexpr size_t MaxBytes=48*1024;
inline uint32_t crc(const uint8_t* p,size_t n){uint32_t c=~0u;for(size_t i=0;i<n;++i){c^=p[i];for(unsigned k=0;k<8;++k)c=(c>>1)^((0u-(c&1u))&0xedb88320u);}return ~c;}
struct Output {uint8_t*p;size_t cap,at=0;bool ok=true;void number(uint32_t v,unsigned n=4){for(unsigned i=0;i<n;++i){if(at>=cap){ok=false;return;}p[at++]=uint8_t(v>>(i*8));}}void text(const char*s,size_t capText){size_t n=strnlen(s,capText);if(n==capText||!Tab5MeshtasticProtocol::utf8((const uint8_t*)s,n)){ok=false;return;}number(n,1);for(size_t i=0;i<n;++i)number(uint8_t(s[i]),1);}};
struct Input {const uint8_t*p;size_t size,at=0;bool ok=true;uint32_t number(unsigned n=4){if(n>size-at){ok=false;return 0;}uint32_t v=0;for(unsigned i=0;i<n;++i)v|=uint32_t(p[at++])<<(8*i);return v;}void text(char*s,size_t cap){size_t n=number(1);if(!ok||n>=cap||n>size-at||!Tab5MeshtasticProtocol::utf8(p+at,n)){ok=false;return;}memcpy(s,p+at,n);s[n]=0;at+=n;}};
inline size_t encode(const Tab5MeshModel::History& h,uint8_t*out,size_t cap){using namespace Tab5MeshModel;if(!out||h.nodeCount>MaxNodes||h.messageCount>MaxMessages||h.messageStart>=MaxMessages)return 0;Output w{out,cap};w.number(0x3148534d);w.number(h.sequence);w.number(h.nodeCount,1);w.number(h.messageCount,2);
 for(unsigned i=0;i<h.nodeCount;++i){auto&n=h.nodes[i];if(!n.id||(n.hasPosition&&!coordinates(n.latitude,n.longitude)))return 0;for(unsigned j=0;j<i;++j)if(h.nodes[j].id==n.id)return 0;w.number(n.id);w.number(n.positionTime);w.number(uint32_t(n.latitude));w.number(uint32_t(n.longitude));w.number(n.hasPosition,1);w.text(n.name,sizeof(n.name));}
 for(unsigned i=0;i<h.messageCount;++i){auto&m=h.messages[(h.messageStart+i)%MaxMessages];if(m.channel>7||(m.outgoing&&m.unread)||(m.hasPosition&&!coordinates(m.latitude,m.longitude)))return 0;w.number(m.from);w.number(m.to);w.number(m.id);w.number(m.time);w.number(m.positionTime);w.number(uint32_t(m.latitude));w.number(uint32_t(m.longitude));w.number(m.channel,1);w.number((m.outgoing?1:0)|(m.positionOnly?2:0)|(m.hasPosition?4:0)|(m.unread?8:0),1);w.text(m.text,sizeof(m.text));}
 if(!w.ok)return 0;uint32_t sum=crc(out,w.at);w.number(sum);return w.ok?w.at:0;}
inline bool decode(const uint8_t* p,size_t n,Tab5MeshModel::History& out){using namespace Tab5MeshModel;if(!p||n<15||n>MaxBytes)return false;Input tail{p+n-4,4};if(crc(p,n-4)!=tail.number())return false;Input r{p,n-4};if(r.number()!=0x3148534d)return false;out={};out.sequence=r.number();out.nodeCount=r.number(1);out.messageCount=r.number(2);if(out.nodeCount>MaxNodes||out.messageCount>MaxMessages)return false;
 for(unsigned i=0;i<out.nodeCount;++i){auto&x=out.nodes[i];x.id=r.number();x.positionTime=r.number();x.latitude=int32_t(r.number());x.longitude=int32_t(r.number());unsigned f=r.number(1);x.hasPosition=f; r.text(x.name,sizeof(x.name));if(!r.ok||!x.id||f>1||(f&&!coordinates(x.latitude,x.longitude)))return false;for(unsigned j=0;j<i;++j)if(out.nodes[j].id==x.id)return false;}
 for(unsigned i=0;i<out.messageCount;++i){auto&x=out.messages[i];x.from=r.number();x.to=r.number();x.id=r.number();x.time=r.number();x.positionTime=r.number();x.latitude=int32_t(r.number());x.longitude=int32_t(r.number());x.channel=r.number(1);unsigned f=r.number(1);x.outgoing=f&1;x.positionOnly=f&2;x.hasPosition=f&4;x.unread=f&8;r.text(x.text,sizeof(x.text));if(!r.ok||x.channel>7||f>15||(x.hasPosition&&!coordinates(x.latitude,x.longitude))||(x.outgoing&&x.unread))return false;}
 return r.ok&&r.at==r.size;}
constexpr size_t PreferenceBytes=512;
inline size_t encode(const Tab5MeshModel::Preferences& v,uint8_t*out,size_t cap){using namespace Tab5MeshModel;if(!out||v.knownCount>MaxKnown||(!v.knownCount?v.preferred!=0:v.preferred>=v.knownCount))return 0;Output w{out,cap};w.number(0x3150534d);w.number((v.options.autoReconnect?1:0)|(v.options.background?2:0)|(v.options.showOnMap?4:0),1);w.number(v.knownCount,1);w.number(v.preferred,1);for(unsigned i=0;i<v.knownCount;++i){auto&k=v.known[i];if(k.type>3)return 0;for(unsigned j=0;j<i;++j)if(sameAddress(v.known[j],k.type,k.address))return 0;w.number(k.type,1);for(auto a:k.address)w.number(a,1);w.number(k.unpaired,1);w.number(k.lastUsed);w.text(k.name,sizeof(k.name));}if(!w.ok)return 0;w.number(crc(out,w.at));return w.ok?w.at:0;}
inline bool decode(const uint8_t*p,size_t n,Tab5MeshModel::Preferences&out){using namespace Tab5MeshModel;if(!p||n<11||n>PreferenceBytes)return false;Input tail{p+n-4,4};if(crc(p,n-4)!=tail.number())return false;Input r{p,n-4};if(r.number()!=0x3150534d)return false;Preferences v;unsigned flags=r.number(1);if(flags>7)return false;v.options={bool(flags&1),bool(flags&2),bool(flags&4)};v.knownCount=r.number(1);v.preferred=r.number(1);if(v.knownCount>MaxKnown||(!v.knownCount?v.preferred!=0:v.preferred>=v.knownCount))return false;for(unsigned i=0;i<v.knownCount;++i){auto&k=v.known[i];k.type=r.number(1);for(auto&a:k.address)a=r.number(1);unsigned flag=r.number(1);k.unpaired=flag;k.lastUsed=r.number();r.text(k.name,sizeof(k.name));if(k.type>3||flag>1||!r.ok)return false;for(unsigned j=0;j<i;++j)if(sameAddress(v.known[j],k.type,k.address))return false;}if(!r.ok||r.at!=r.size)return false;out=v;return true;}
}
